// Offline city lookup for the travel map. Bundled dataset (cities >= 30k pop +
// capitals) generated by scripts/gen-cities.cjs. Rows are compact:
// { n: name, c: countryAlpha2, y: lat, x: lon, p: population }.
import DATA from "../data/cities.json";

const strip = (s) =>
  (s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");

// Search by name (accent-insensitive). Prefix matches rank above substring, and
// within each, higher population first. Returns normalized city objects.
export function searchCities(query, limit = 8) {
  const q = strip(query).trim();
  if (q.length < 2) return [];
  const prefix = [];
  const other = [];
  for (const r of DATA) {
    const n = strip(r.n);
    if (n.startsWith(q)) prefix.push(r);
    else if (n.includes(q)) other.push(r);
    if (prefix.length >= limit * 3) break;
  }
  const byPop = (a, b) => b.p - a.p;
  prefix.sort(byPop);
  other.sort(byPop);
  return [...prefix, ...other].slice(0, limit).map(toCity);
}

function toCity(r) {
  return { name: r.n, country: r.c, lat: r.y, lon: r.x };
}
